# First, find which 8s have horizontal neighbors (these won't become 2)
horiz_connected = set()
for r in range(11):
    for c in range(17):
        if input_grid[r][c] == 8:
            if c > 0 and input_grid[r][c-1] == 8:
                horiz_connected.add((r, c))
            if c < 16 and input_grid[r][c+1] == 8:
                horiz_connected.add((r, c))

print("Horizontally connected 8s:", sorted(horiz_connected))

# Now find vertical components among non-horizontally-connected 8s
vertical_components = []
visited = set()

non_horiz_8s = set()
for r in range(11):
    for c in range(17):
        if input_grid[r][c] == 8 and (r,c) not in horiz_connected:
            non_horiz_8s.add((r,c))

print("\nNon-horizontally-connected 8s:", sorted(non_horiz_8s))

# Find vertical connectivity among these
def find_vertical_component(grid, start_pos):
    """Find all vertically-connected 8s from start position"""
    comp = set()
    stack = [start_pos]
    while stack:
        r, c = stack.pop()
        if (r, c) in visited or (r,c) not in non_horiz_8s:
            continue
        visited.add((r, c))
        comp.add((r, c))

        # Check up and down
        if r > 0 and grid[r-1][c] == 8:
            if (r-1, c) not in visited and (r-1, c) in non_horiz_8s:
                stack.append((r-1, c))
        if r < len(grid)-1 and grid[r+1][c] == 8:
            if (r+1, c) not in visited and (r+1, c) in non_horiz_8s:
                stack.append((r+1, c))
    return comp

for r, c in non_horiz_8s:
